import { useState, useRef, useEffect } from "react";
import { useGSAP } from "../hooks/useGSAP";
import { Typewriter, SkillBar, Modal } from "../components/Shared";
import { DevBadge } from "../components/DeveloperMode";
import { PROJECTS, SKILLS, TECH, SERVICES, TIMELINE, CONTACT_INFO } from "../data/content";

export function LightLayout({ theme, devMode, scrollTo, tIdx, setTIdx, sel, setSel, sent, setSent, form, setForm }) {
  const heroRef=useRef(null),heroTitleRef=useRef(null),heroBadgeRef=useRef(null),heroCtaRef=useRef(null);
  const servicesRef=useRef(null),timelineRef=useRef(null),contactRef=useRef(null);
  const [mousePos, setMousePos] = useState({ x: 0, y: 0 });

  // Track mouse movement for interactive background
  useEffect(() => {
    const handleMouseMove = (e) => {
      setMousePos({ x: e.clientX, y: e.clientY });
    };
    window.addEventListener('mousemove', handleMouseMove);
    return () => window.removeEventListener('mousemove', handleMouseMove);
  }, []);

  useGSAP((gsap,ST)=>{
    const tl=gsap.timeline({delay:.2});
    tl.fromTo(heroBadgeRef.current,{y:16,opacity:0},{y:0,opacity:1,duration:.65,ease:"expo.out"})
      .fromTo(heroTitleRef.current,{y:40,opacity:0},{y:0,opacity:1,duration:1,ease:"expo.out"},"-=.25")
      .fromTo(heroCtaRef.current,{y:16,opacity:0},{y:0,opacity:1,duration:.65,ease:"expo.out"},"-=.35");

    // 3D scrolling animations for background name elements
    gsap.to(".name-bg",{
      yPercent:20,
      scale:1.08,
      rotationX:3,
      rotationY:2,
      ease:"none",
      scrollTrigger:{
        trigger:heroRef.current,
        start:"top top",
        end:"bottom top",
        scrub:1.8
      }
    });

    gsap.to(".name-float-1",{
      xPercent:25,
      yPercent:15,
      rotation:18,
      scale:0.92,
      opacity:0.015,
      ease:"none",
      scrollTrigger:{
        trigger:heroRef.current,
        start:"top top",
        end:"bottom top",
        scrub:1.4
      }
    });

    gsap.to(".name-float-2",{
      xPercent:-20,
      yPercent:-18,
      rotation:-15,
      scale:1.1,
      opacity:0.012,
      ease:"none",
      scrollTrigger:{
        trigger:heroRef.current,
        start:"top top",
        end:"bottom top",
        scrub:1.6
      }
    });

    const sc=servicesRef.current?.querySelectorAll(".srv-card");
    if(sc)gsap.fromTo(sc,{y:30,opacity:0},{y:0,opacity:1,stagger:.08,duration:.75,ease:"expo.out",scrollTrigger:{trigger:servicesRef.current,start:"top 84%"}});
    const ti=timelineRef.current?.querySelectorAll(".tl-step");
    if(ti)gsap.fromTo(ti,{y:20,opacity:0},{y:0,opacity:1,stagger:.14,duration:.7,ease:"expo.out",scrollTrigger:{trigger:timelineRef.current,start:"top 84%"}});
    gsap.fromTo(contactRef.current,{y:24,opacity:0},{y:0,opacity:1,duration:.8,ease:"expo.out",scrollTrigger:{trigger:contactRef.current,start:"top 86%"}});
  },[]);

  return <>
    {/* Interactive Grid Background for entire theme */}
    <div style={{position:"fixed",inset:0,pointerEvents:"none",overflow:"hidden",zIndex:0}}>
      <div style={{
        position: "absolute",
        width: "200%",
        height: "200%",
        top: "50%",
        left: "50%",
        transform: `translate(-50%, -50%) translate(${(mousePos.x - window.innerWidth/2) * 0.02}px, ${(mousePos.y - window.innerHeight/2) * 0.02}px)`,
        backgroundImage: `linear-gradient(${theme.animFg} 1px, transparent 1px), linear-gradient(90deg, ${theme.animFg} 1px, transparent 1px)`,
        backgroundSize: "48px 48px",
        transition: "transform 0.3s ease-out",
        opacity: 0.6
      }}/>
    </div>

    {/* Main content with higher z-index */}
    <div style={{position:"relative",zIndex:1}}>
    {/* HERO — clean left-aligned with image on right */}
    <section ref={heroRef} id="hero" className="hero-section" style={{minHeight:"92vh",display:"flex",flexDirection:"row",alignItems:"center",justifyContent:"space-between",padding:"120px 60px 80px",position:"relative",borderBottom:`1px solid ${theme.border}`,"@media (max-width: 1024px)": {flexDirection:"column",padding:"120px 40px 80px"}}}>
      {/* Large blurred name in background */}
      <div className="name-bg" style={{
        position:"absolute",
        top:"50%",
        left:"50%",
        transform:"translate(-50%, -50%)",
        fontSize:"clamp(120px,20vw,360px)",
        fontWeight:900,
        fontFamily:"'Syne', sans-serif",
        color:theme.accent,
        opacity:0.04,
        filter:"blur(3.5px)",
        letterSpacing:"-0.03em",
        pointerEvents:"none",
        zIndex:0,
        whiteSpace:"nowrap",
        textTransform:"uppercase",
        "@media (max-width: 768px)": {
          fontSize:"clamp(80px,16vw,280px)",
          opacity:0.06
        }
      }}>GAITHO</div>

      {/* Additional floating name elements for 3D effect */}
      <div className="name-float-1" style={{
        position:"absolute",
        top:"25%",
        right:"15%",
        fontSize:"clamp(45px,6vw,120px)",
        fontWeight:800,
        fontFamily:"'Space Mono', monospace",
        color:theme.animOrb,
        opacity:0.03,
        filter:"blur(2.5px)",
        pointerEvents:"none",
        zIndex:0,
        transform:"rotate(12deg)",
        "@media (max-width: 768px)": {
          fontSize:"clamp(35px,5vw,80px)",
          opacity:0.05,
          top:"20%",
          right:"10%"
        }
      }}>MICHAEL</div>

      <div className="name-float-2" style={{
        position:"absolute",
        bottom:"30%",
        left:"12%",
        fontSize:"clamp(35px,5vw,90px)",
        fontWeight:700,
        fontFamily:"'Syne', sans-serif",
        color:theme.animDot,
        opacity:0.025,
        filter:"blur(3px)",
        pointerEvents:"none",
        zIndex:0,
        transform:"rotate(-8deg)",
        "@media (max-width: 768px)": {
          fontSize:"clamp(25px,4vw,60px)",
          opacity:0.04,
          bottom:"25%",
          left:"8%"
        }
      }}>DEVELOPER</div>

      {/* Left side - Hero content */}
      <div className="hero-content" style={{position:"relative",zIndex:1,maxWidth:680,width:"100%","@media (max-width: 1024px)": {maxWidth:"100%",marginBottom:60}}}>
        <h1 ref={heroTitleRef} className="hero-title" style={{fontFamily:"'Syne',sans-serif",fontSize:"clamp(32px,6vw,72px)",fontWeight:800,lineHeight:1.0,letterSpacing:"-.03em",marginBottom:20,color:theme.text}}>
          Michael Gaitho.<span style={{color:theme.accent}}>DEV</span>
        </h1>
        <p className="hero-subtitle" style={{fontSize:18,color:theme.textMuted,maxWidth:440,margin:"0 0 12px 0",lineHeight:1.9}}>UI/UX Designer & Creative Coder based in Nakuru, Kenya 🇰🇪</p>
        <p className="hero-description" style={{fontSize:15,color:theme.textMuted,maxWidth:380,margin:"0 0 40px 0",lineHeight:1.85,opacity:.7}}>Building clean, performant React applications with beautiful motion design.</p>
        <div ref={heroCtaRef} className="hero-cta" style={{display:"flex",gap:12,justifyContent:"flex-start",flexWrap:"wrap"}}>
          <button className="bp" onClick={()=>scrollTo("projects")} style={{borderRadius:4}}>View Projects</button>
          <button className="bg" onClick={()=>scrollTo("contact")} style={{borderRadius:4}}>Say Hello →</button>
        </div>
      </div>

      {/* Right side - Software Developer image */}
      <div style={{position:"relative",zIndex:1,width:"75%",maxWidth:1100,"@media (max-width: 1024px)": {width:"100%",maxWidth:900}}}>
        <img
          src="/SOFTWARE DEVELOPER (1).png"
          alt="Software Developer"
          style={{
            width: "100%",
            height: "auto",
            objectFit: "contain",
            borderRadius: 12,
            maxHeight: "95vh",
            mixBlendMode: "multiply"
          }}
        />
      </div>

      {devMode&&<DevBadge id="hero" devMode={devMode} theme={theme}/>}
    </section>

    <div style={{overflow:"hidden",borderBottom:`1px solid ${theme.border}`,padding:"9px 0"}}>
      <div style={{display:"flex",gap:30,whiteSpace:"nowrap",animation:"marquee 25s linear infinite"}}>
        {[...TECH,...TECH].map((t,i)=><span key={i} style={{fontSize:14,fontWeight:600,letterSpacing:".15em",textTransform:"uppercase",color:theme.text,opacity:.6}}>{t.name}<span style={{marginLeft:16,opacity:.2}}>·</span></span>)}
      </div>
    </div>

    {/* ABOUT — three-column open cards */}
    <section id="about" className="about-section" style={{padding:"100px 60px",position:"relative",borderBottom:`1px solid ${theme.border}`}}>
      <div style={{maxWidth:1100,margin:"0 auto"}}>
        <div style={{textAlign:"center",marginBottom:60}}>
          <span style={{fontSize:14,letterSpacing:".25em",textTransform:"uppercase",color:theme.text,fontFamily:"'Space Mono',monospace",opacity:.8,display:"block",marginBottom:12}}>About</span>
          <h2 className="section-title" style={{fontFamily:"'Syne',sans-serif",fontSize:"clamp(26px,4vw,42px)",fontWeight:800,letterSpacing:"-.02em",color:theme.text}}>Who I Am</h2>
        </div>
        <div className="about-cards" style={{display:"grid",gridTemplateColumns:"repeat(3,1fr)",gap:20}}>
          <div className="about-card" style={{background:"transparent",border:`1px solid ${theme.border}`,borderRadius:8,padding:32,boxShadow:theme.shadow}}>
            <div className="icon" style={{fontSize:16,marginBottom:18,opacity:.3}}>•</div>
            <h3 style={{fontFamily:"'Syne',sans-serif",fontSize:19,fontWeight:700,marginBottom:10,color:theme.text}}>Michael Gaitho</h3>
            <p style={{color:theme.textMuted,fontSize:15,lineHeight:1.8}}>Frontend Developer & UI/UX designer specializing in AI-powered interfaces and real-time analytics.</p>
          </div>
          <div className="about-card" style={{background:"transparent",border:`1px solid ${theme.border}`,borderRadius:8,padding:32,boxShadow:theme.shadow}}>
            <div className="icon" style={{fontSize:16,marginBottom:18,opacity:.3}}>–</div>
            <h3 style={{fontFamily:"'Syne',sans-serif",fontSize:19,fontWeight:700,marginBottom:10,color:theme.text}}>AI Development</h3>
            <p style={{color:theme.textMuted,fontSize:15,lineHeight:1.8}}>Building AI-powered web interfaces and dashboards. Leading frontend architecture and UI/UX design decisions.</p>
          </div>
          <div className="about-card" style={{background:"transparent",border:`1px solid ${theme.accent}`,borderRadius:8,padding:32,boxShadow:theme.shadow}}>
            <div className="icon" style={{fontSize:16,marginBottom:18,opacity:.35}}>◦</div>
            <h3 style={{fontFamily:"'Syne',sans-serif",fontSize:19,fontWeight:700,marginBottom:10,color:theme.text}}>Education</h3>
            <p style={{color:theme.textMuted,fontSize:15,lineHeight:1.8}}>Bachelor of IT — Specializing in software engineering and human-computer interaction.</p>
          </div>
        </div>
        <div style={{marginTop:24,display:"flex",gap:10,justifyContent:"center"}}><button className="bp" onClick={() => window.open('/resume.pdf', '_blank')} style={{borderRadius:4}}>Download Resume</button><button className="bg" onClick={()=>scrollTo("projects")} style={{borderRadius:4}}>See Work →</button></div>
      </div>
      {devMode&&<DevBadge id="about" devMode={devMode} theme={theme}/>}
    </section>

    {/* SKILLS — dot-grid indicators */}
    <section id="skills" className="skills-section" style={{padding:"100px 60px",borderBottom:`1px solid ${theme.border}`,position:"relative",'@media (max-width: 768px)': {padding:"60px 30px"}, '@media (max-width: 480px)': {padding:"40px 20px"}}}>
      <div style={{maxWidth:1100,margin:"0 auto"}}>
        <div style={{textAlign:"center",marginBottom:56}}>
          <span style={{fontSize:14,letterSpacing:".25em",textTransform:"uppercase",color:theme.text,fontFamily:"'Space Mono',monospace",opacity:.8,display:"block",marginBottom:12}}>Expertise</span>
          <h2 className="section-title" style={{fontFamily:"'Syne',sans-serif",fontSize:"clamp(26px,4vw,42px)",fontWeight:800,letterSpacing:"-.02em",color:theme.text}}>Skills</h2>
        </div>
        <div className="skills-grid" style={{display:"grid",gridTemplateColumns:"1fr 1fr",gap:50,'@media (max-width: 768px)': {gridTemplateColumns:"1fr",gap:30}}}>
          <div>{SKILLS.map((s,i)=><div key={s.label} className="skill-item" style={{marginBottom:18}}>
            <div style={{display:"flex",justifyContent:"space-between",marginBottom:8}}>
              <span style={{fontSize:14,fontWeight:500,color:theme.text,opacity:.82}}>{s.label}</span>
              <span style={{fontSize:14,color:theme.text,fontFamily:"'Space Mono',monospace",opacity:.8}}>{s.pct}%</span>
            </div>
            {/* Dot progress */}
            <div style={{display:"flex",gap:4}}>
              {Array.from({length:10},(_,d)=><div key={d} style={{width:18,height:4,borderRadius:2,background:d<Math.round(s.pct/10)?theme.accent:theme.border,opacity:d<Math.round(s.pct/10)?.65:.4,transition:"background .3s"}}/>)}
            </div>
          </div>)}</div>
          <div>
            <h3 style={{fontFamily:"'Syne',sans-serif",fontSize:17,fontWeight:700,marginBottom:18,color:theme.text,letterSpacing:".08em",textTransform:"uppercase",opacity:.8}}>Tech Stack</h3>
            <div style={{display:"flex",flexWrap:"wrap",gap:12}}>
              {TECH.map((t,i)=>{
                const [h,setH]=useState(false);
                return (
                  <div 
                    key={i} 
                    onMouseEnter={()=>setH(true)} 
                    onMouseLeave={()=>setH(false)}
                    style={{
                      display:"flex",
                      alignItems:"center",
                      gap:8,
                      padding:"10px 16px",
                      background:h?"rgba(0,0,0,0.05)":"transparent",
                      borderRadius:8,
                      transition:"all .2s",
                      cursor:"default",
                      boxShadow:h?theme.shadowMd:theme.shadow
                    }}
                  >
                    <img 
                      src={t.colorLogo} 
                      alt={t.name}
                      style={{
                        width:28,
                        height:28,
                        transition:"all .2s"
                      }}
                    />
                    <span style={{fontSize:14,fontWeight:500,color:theme.text,opacity:.8}}>{t.name}</span>
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>
      {devMode&&<DevBadge id="skills" devMode={devMode} theme={theme}/>}
    </section>

    {/* PROJECTS — large case study cards */}
    <section id="projects" className="projects-section" style={{padding:"100px 60px",borderBottom:`1px solid ${theme.border}`,position:"relative"}}>
      <div style={{maxWidth:1200,margin:"0 auto"}}>
        <div style={{textAlign:"left",marginBottom:40}}>
          <span style={{fontSize:14,letterSpacing:".25em",textTransform:"uppercase",color:theme.text,fontFamily:"'Space Mono',monospace",opacity:.8,display:"block",marginBottom:12}}>Selected Work</span>
          <h2 className="section-title" style={{fontFamily:"'Syne',sans-serif",fontSize:"clamp(30px,4vw,44px)",fontWeight:800,letterSpacing:"-.02em",marginBottom:16,color:theme.text}}>Selected Work</h2>
          <p style={{fontSize:16,color:theme.textMuted,lineHeight:1.75,maxWidth:600}}>A selection of enterprise engagements — from greenfield architecture to complex systems integration at scale.</p>
        </div>
        <div className="projects-grid" style={{display:"grid",gridTemplateColumns:"repeat(2,1fr)",gap:24,'@media (max-width: 768px)': {gridTemplateColumns:"1fr"}}}>
          {PROJECTS.map((p)=>{
            const [h,setH]=useState(false);
            return (
              <div 
                key={p.id} 
                onMouseEnter={()=>setH(true)} 
                onMouseLeave={()=>setH(false)} 
                style={{
                  background:"transparent",
                  border:`1px solid ${h?theme.borderMid:theme.border}`,
                  borderRadius:16,
                  overflow:"hidden",
                  transform:h?"translateY(-4px)":"translateY(0)",
                  transition:"all .28s",
                  boxShadow:h?theme.shadowMd:theme.shadow
                }}
              >
                {/* Card Top — Image/Background Area */}
                <div style={{
                  height:320,
                  background:p.image ? `url(${p.image}) center/cover no-repeat` : p.cardBg,
                  display:"flex",
                  flexDirection:"column",
                  alignItems:"center",
                  justifyContent:"center",
                  position:"relative",
                  padding:"0 40px"
                }}>
                  {/* Dark Overlay */}
                  {p.image && <div style={{
                    position:"absolute",
                    inset:0,
                    background:"rgba(0,0,0,0.5)",
                    zIndex:1
                  }} />}

                  {/* LIVE Badge */}
                  <div style={{
                    position:"absolute",
                    top:20,
                    right:20,
                    display:"flex",
                    alignItems:"center",
                    gap:8,
                    background:"rgba(0,0,0,0.4)",
                    backdropFilter:"blur(10px)",
                    padding:"6px 12px",
                    borderRadius:6,
                    border:"1px solid rgba(255,255,255,0.15)",
                    zIndex:2
                  }}>
                    <div style={{width:6,height:6,borderRadius:"50%",background:"#00FF88",boxShadow:"0 0 8px #00FF88"}} />
                    <span style={{fontSize:14,fontWeight:600,color:"#fff",letterSpacing:".1em",textTransform:"uppercase"}}>LIVE</span>
                  </div>

                  {/* Title & Category */}
                  <h3 style={{
                    fontSize:"clamp(20px,3vw,28px)",
                    fontWeight:800,
                    fontFamily:"'Syne',sans-serif",
                    color:"#fff",
                    textAlign:"center",
                    margin:0,
                    textShadow:"0 2px 20px rgba(0,0,0,0.3)",
                    position:"relative",
                    zIndex:2
                  }}>{p.title}</h3>
                  <span style={{
                    fontSize:14,
                    letterSpacing:".2em",
                    textTransform:"uppercase",
                    color:"rgba(255,255,255,0.7)",
                    marginTop:8,
                    fontWeight:600,
                    position:"relative",
                    zIndex:2
                  }}>{p.category}</span>
                </div>

                {/* Card Bottom — Meta Info */}
                <div style={{padding:"24px 28px 28px"}}>
                  {/* Ultra-minimal project type indicator */}
                  <div style={{
                    fontSize:11,
                    fontWeight:600,
                    color:theme.textMuted,
                    letterSpacing:".1em",
                    textTransform:"uppercase",
                    marginBottom:16,
                    opacity:0.7
                  }}>
                    {p.category}
                  </div>

                  {/* Description */}
                  <p style={{fontSize:15,color:theme.textMuted,lineHeight:1.75,marginBottom:20,opacity:.9}}>{p.longDesc}</p>

                  {/* Tech Stack Tags */}
                  <div style={{display:"flex",flexWrap:"wrap",gap:8}}>
                    {p.stack.map((tech)=>{
                      const [tH,setTH]=useState(false);
                      return (
                        <span 
                          key={tech} 
                          onMouseEnter={()=>setTH(true)} 
                          onMouseLeave={()=>setTH(false)}
                          style={{
                            padding:"6px 12px",
                            border:`1px solid ${tH?theme.accent:theme.border}`,
                            borderRadius:6,
                            fontSize:14,
                            fontWeight:500,
                            color:theme.text,
                            opacity:.75,
                            transition:"all .2s",
                            cursor:"default",
                            letterSpacing:".02em"
                          }}
                        >{tech}</span>
                      );
                    })}
                  </div>

                  {/* Live Demo Arrow */}
                  {p.liveUrl && (
                    <a 
                      href={p.liveUrl} 
                      target="_blank" 
                      rel="noopener noreferrer"
                      style={{
                        display:"inline-flex",
                        alignItems:"center",
                        gap:8,
                        marginTop:20,
                        padding:"8px 16px",
                        border:`1px solid ${theme.border}`,
                        borderRadius:6,
                        fontSize:14,
                        fontWeight:600,
                        color:theme.text,
                        textDecoration:"none",
                        opacity:.6,
                        transition:"all .2s",
                        letterSpacing:".08em"
                      }}
                      onMouseEnter={e=>{
                        e.target.style.borderColor=theme.accent;
                        e.target.style.opacity=1;
                      }}
                      onMouseLeave={e=>{
                        e.target.style.borderColor=theme.border;
                        e.target.style.opacity=.6;
                      }}
                    >
                      <span>Live Demo</span>
                      <span style={{fontSize:14,transform:"translateX(2px)"}}>→</span>
                    </a>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>
      {devMode&&<DevBadge id="projects" devMode={devMode} theme={theme}/>}
    </section>

    {/* TIMELINE — creative horizontal with large year badges */}
    <section ref={timelineRef} id="experience" className="timeline-section" style={{padding:"100px 60px",borderBottom:`1px solid ${theme.border}`,position:"relative"}}>
      <div style={{maxWidth:1100,margin:"0 auto"}}>
        <div style={{textAlign:"center",marginBottom:60}}><span style={{fontSize:13,letterSpacing:".25em",textTransform:"uppercase",color:theme.textMuted,fontFamily:"'Space Mono',monospace",opacity:.6,display:"block",marginBottom:12}}>Journey</span><h2 className="section-title" style={{fontFamily:"'Syne',sans-serif",fontSize:"clamp(26px,4vw,42px)",fontWeight:800,letterSpacing:"-.02em",color:theme.text}}>Experience & Education</h2></div>
        {/* Creative horizontal layout */}
        <div style={{display:"flex",flexDirection:"column",gap:40}}>
          {TIMELINE.map((t,i)=><div key={i} style={{display:"flex",gap:32,alignItems:"center",position:"relative"}}>
            <div style={{width:120,flexShrink:0,textAlign:"right"}}>
              <div style={{fontFamily:"'Syne',sans-serif",fontSize:48,fontWeight:800,color:theme.accent,opacity:.3,lineHeight:1}}>{t.year.slice(-2)}</div>
              <div style={{fontFamily:"'Space Mono',monospace",fontSize:12,fontWeight:700,color:theme.textMuted,letterSpacing:".08em",textTransform:"uppercase",opacity:.7}}>{t.place}</div>
            </div>
            <div style={{width:16,height:16,borderRadius:"50%",background:theme.accent,flexShrink:0}}/>
            <div style={{flex:1,background:"transparent",border:`1px solid ${theme.border}`,borderRadius:12,padding:24,transition:"all .3s"}}
              onMouseEnter={e=>{e.currentTarget.style.borderColor=theme.accent;e.currentTarget.style.transform="translateX(8px)";}}
              onMouseLeave={e=>{e.currentTarget.style.borderColor=theme.border;e.currentTarget.style.transform="translateX(0)";}}>
              <div style={{display:"flex",alignItems:"center",gap:10,marginBottom:12}}>
                <span style={{fontSize:20,opacity:.5}}>{t.type==="edu"?"◦":"■"}</span>
                <h3 style={{fontFamily:"'Syne',sans-serif",fontSize:18,fontWeight:700,color:theme.text,opacity:.9}}>{t.title}</h3>
              </div>
              <p style={{fontSize:14,color:theme.textMuted,lineHeight:1.75,opacity:.75}}>{t.desc}</p>
            </div>
          </div>)}
        </div>
      </div>
      {devMode&&<DevBadge id="experience" devMode={devMode} theme={theme}/>}
    </section>

    {/* SERVICES — single card with vertical layout */}
    <section ref={servicesRef} id="services" className="services-section" style={{padding:"100px 60px",borderBottom:`1px solid ${theme.border}`,position:"relative"}}>
      <div style={{maxWidth:1100,margin:"0 auto"}}>
        <div style={{textAlign:"center",marginBottom:56}}><span style={{fontSize:13,letterSpacing:".25em",textTransform:"uppercase",color:theme.textMuted,fontFamily:"'Space Mono',monospace",opacity:.6,display:"block",marginBottom:12}}>Services</span><h2 className="section-title" style={{fontFamily:"'Syne',sans-serif",fontSize:"clamp(26px,4vw,42px)",fontWeight:800,letterSpacing:"-.02em",color:theme.text}}>What I Do</h2></div>
        {(() => {
          const [cardHover, setCardHover] = useState(false);
          return (
            <div 
              className="services-card" 
              onMouseEnter={() => setCardHover(true)}
              onMouseLeave={() => setCardHover(false)}
              style={{background:"transparent",border:`1px solid rgba(60, 96, 87, ${cardHover ? 0.7 : 0.3})`,borderRadius:12,padding:"30px",transition:"border-color .2s"}}
            >
              <div style={{display:"flex",flexDirection:"column",gap:0}}>
                {SERVICES.map((s,i)=><div key={s.title} className="srv-item" style={{display:"flex",alignItems:"flex-start",gap:28,padding:"35px 40px",background:"transparent",borderRadius:8,transition:"background .2s",cursor:"default",borderBottom:i===SERVICES.length-1?"none":`1px solid rgba(60, 96, 87, ${cardHover ? 0.7 : 0.3})`}}
                  onMouseEnter={e=>{e.currentTarget.style.background="rgba(0,0,0,0.03)";}}
                  onMouseLeave={e=>{e.currentTarget.style.background="transparent";}}>
                  <div style={{fontSize:36,opacity:.4,lineHeight:1,flexShrink:0,marginTop:2}}>{s.icon}</div>
                  <div>
                    <h3 style={{fontFamily:"'Syne',sans-serif",fontSize:19,fontWeight:700,marginBottom:10,color:theme.text}}>{s.title}</h3>
                    <p style={{fontSize:15,color:theme.textMuted,lineHeight:1.8}}>{s.desc}</p>
                  </div>
                </div>)}
              </div>
            </div>
          );
        })()}
      </div>
      {devMode&&<DevBadge id="services" devMode={devMode} theme={theme}/>}
    </section>

    {/* GET IN TOUCH */}
    <section className="contact-section" style={{padding:"100px 60px",borderBottom:`1px solid ${theme.border}`}}>
      <div style={{maxWidth:680,margin:"0 auto",textAlign:"center"}}>
        <span style={{fontSize:13,letterSpacing:".25em",textTransform:"uppercase",color:theme.textMuted,fontFamily:"'Space Mono',monospace",opacity:.6,display:"block",marginBottom:12}}>Connect</span>
        <h2 className="section-title" style={{fontFamily:"'Syne',sans-serif",fontSize:"clamp(26px,4vw,42px)",fontWeight:800,letterSpacing:"-.02em",color:theme.text,marginBottom:40}}>Let's Work Together</h2>
        <p style={{fontSize:16,lineHeight:1.9,color:theme.text,opacity:.8,marginBottom:40}}>I'm always interested in hearing about new projects and opportunities. Whether you have a question or just want to say hi, feel free to reach out!</p>
        <div className="contact-info-grid" style={{display:"grid",gridTemplateColumns:"repeat(auto-fit,minmax(200px,1fr))",gap:20,marginBottom:40}}>
          {CONTACT_INFO.map((c,i)=>(
            <a key={i} href={c.link} target="_blank" rel="noopener noreferrer" style={{background:theme.surface,border:`1px solid ${theme.border}`,borderRadius:12,padding:"24px 20px",textDecoration:"none",display:"flex",flexDirection:"column",alignItems:"center",gap:12,transition:"all .3s",opacity:.9}} onMouseOver={e=>{e.currentTarget.style.transform="translateY(-4px)";e.currentTarget.style.borderColor=theme.accent;e.currentTarget.style.opacity=1}} onMouseOut={e=>{e.currentTarget.style.transform="translateY(0)";e.currentTarget.style.borderColor=theme.border;e.currentTarget.style.opacity=.9}}>
              <div style={{fontSize:22,opacity:.4}}>{c.icon}</div>
              <div style={{fontSize:15,fontWeight:600,color:theme.text,fontFamily:"'Syne',sans-serif"}}>{c.title}</div>
              <div style={{fontSize:14,color:theme.textMuted,opacity:.8}}>{c.value}</div>
            </a>
          ))}
        </div>
      </div>
    </section>

    {/* CONTACT */}
    <section ref={contactRef} id="contact" className="contact-section" style={{padding:"100px 60px",position:"relative"}}>
      <div className="contact-form" style={{maxWidth:560,margin:"0 auto"}}>
        <div style={{textAlign:"center",marginBottom:40}}>
          <span style={{fontSize:13,letterSpacing:".25em",textTransform:"uppercase",color:theme.textMuted,fontFamily:"'Space Mono',monospace",opacity:.6,display:"block",marginBottom:12}}>Contact</span>
          <h2 className="section-title" style={{fontFamily:"'Syne',sans-serif",fontSize:"clamp(26px,4vw,42px)",fontWeight:800,letterSpacing:"-.02em",marginBottom:12,color:theme.text}}>Let's Build<br/><span style={{color:theme.accent}}>Something Great</span></h2>
        </div>
        <div className="contact-form" style={{background:"transparent",border:`1px solid ${theme.border}`,borderRadius:8,padding:34,boxShadow:theme.shadow}}>
          {sent?<div style={{textAlign:"center",padding:"30px 0"}}><div style={{fontSize:24,marginBottom:16,opacity:.6}}>✓</div><h3 style={{fontFamily:"'Syne',sans-serif",fontSize:20,fontWeight:800,color:theme.text}}>Message Sent!</h3><p style={{color:theme.textMuted,fontSize:14}}>Michael will reply shortly.</p></div>:<>
            {[{l:"Name",k:"name",t:"text",p:"Your name"},{l:"Email",k:"email",t:"email",p:"hello@example.com"},{l:"Subject",k:"subject",t:"text",p:"Project Inquiry"}].map(f=><div key={f.k} style={{marginBottom:14}}>
              <label style={{display:"block",fontSize:12,fontWeight:700,letterSpacing:".17em",textTransform:"uppercase",color:theme.textMuted,marginBottom:6,fontFamily:"'Space Mono',monospace",opacity:.65}}>{f.l}</label>
              <input style={{width:"100%",padding:"12px 15px",background:theme.bgAlt,border:`1px solid ${theme.border}`,borderRadius:5,color:theme.text,fontSize:15,fontFamily:"'DM Sans',sans-serif",outline:"none",transition:"border-color .2s"}} type={f.t} placeholder={f.p} value={form[f.k]} onChange={e=>setForm(d=>({...d,[f.k]:e.target.value}))} onFocus={e=>e.target.style.borderColor=theme.borderMid} onBlur={e=>e.target.style.borderColor=theme.border}/>
            </div>)}
            <div style={{marginBottom:20}}>
              <label style={{display:"block",fontSize:12,fontWeight:700,letterSpacing:".17em",textTransform:"uppercase",color:theme.textMuted,marginBottom:6,fontFamily:"'Space Mono',monospace",opacity:.65}}>Message</label>
              <textarea style={{width:"100%",padding:"12px 15px",background:theme.bgAlt,border:`1px solid ${theme.border}`,borderRadius:5,color:theme.text,fontSize:15,fontFamily:"'DM Sans',sans-serif",outline:"none",resize:"vertical",transition:"border-color .2s"}} rows={5} placeholder="Tell me about your project..." value={form.message} onChange={e=>setForm(d=>({...d,message:e.target.value}))} onFocus={e=>e.target.style.borderColor=theme.borderMid} onBlur={e=>e.target.style.borderColor=theme.border}/>
            </div>
            <button className="bp" onClick={()=>{
              const subject = encodeURIComponent(form.subject || "Portfolio Contact");
              const body = encodeURIComponent(`Name: ${form.name}\nEmail: ${form.email}\n\n${form.message}`);
              window.open(`mailto:michaelgaitho47@gmail.com?subject=${subject}&body=${body}`);
              setSent(true);
            }} style={{width:"100%",display:"flex",justifyContent:"center",fontSize:14,padding:"12px 15px",borderRadius:4}}>Send Message →</button>
          </>}
        </div>
      </div>
      {devMode&&<DevBadge id="contact" devMode={devMode} theme={theme}/>}
    </section>
    </div>
    </>;
}
